import CodeBlock from "./code-block"

export default function Page() {
  return (
    <div className="mx-auto w-full max-w-3xl px-4 py-10 md:px-6 md:py-14">
      <CodeBlock />
    </div>
  )
}

"use client"

import CodeTabs from "./components/code-tabs"
import { useCodeBlock } from "./hooks/use-code-block"
import "./styles/code-block.css"

export default function CodeBlock() {
  const { activeTab, setActiveTab, copied, handleCopy } = useCodeBlock()

  return (
    <div className="cb-root">
      <div className="cb-inner">
        <CodeTabs
          activeTab={activeTab}
          copied={copied}
          onTabChange={setActiveTab}
          onCopy={handleCopy}
        />
      </div>
    </div>
  )
}

"use client"

import * as React from "react"
import { Check, Copy } from "lucide-react"
import { cn } from "@/lib/utils"
import { TAB_OPTIONS, COMMANDS, type TabOption } from "../lib/config"

type Props = {
  activeTab: TabOption
  copied: boolean
  onTabChange: (tab: TabOption) => void
  onCopy: () => void
}

export default function CodeTabs({ activeTab, copied, onTabChange, onCopy }: Props) {
  const tabRefs = React.useRef<(HTMLButtonElement | null)[]>([])
  const [indicator, setIndicator] = React.useState({ left: 0, width: 0 })

  React.useLayoutEffect(() => {
    const idx = TAB_OPTIONS.indexOf(activeTab)
    const el = tabRefs.current[idx]
    if (el) setIndicator({ left: el.offsetLeft, width: el.offsetWidth })
  }, [activeTab])

  const cmd = COMMANDS[activeTab]
  const [pkgManager, action, ...pkgs] = cmd.split(" ")

  return (
    <div className="cb-card">
      {/* Tab row */}
      <div className="cb-tabs">
        {TAB_OPTIONS.map((tab, i) => (
          <button
            key={tab}
            ref={(el) => { tabRefs.current[i] = el }}
            onClick={() => onTabChange(tab)}
            className={cn("cb-tab", activeTab === tab && "cb-tab--active")}
          >
            {tab}
          </button>
        ))}
        <div className="cb-indicator" style={{ left: indicator.left, width: indicator.width }} />
        <div className="cb-indicator-glow" style={{ left: indicator.left, width: indicator.width }} />
      </div>

      {/* Code row */}
      <div className="cb-code">
        <code key={activeTab} className="cb-cmd">
          <span className="cb-syntax-cmd">{pkgManager}</span>
          <span className="cb-syntax-action">{action}</span>
          <span className="cb-syntax-pkg">{pkgs.join(" ")}</span>
        </code>

        <button
          onClick={onCopy}
          className={cn("cb-copy-btn", copied && "cb-copy-btn--copied")}
          title="Copy command"
        >
          {copied ? <Check size={14} /> : <Copy size={14} />}
        </button>
      </div>
    </div>
  )
}

import { useState } from "react"
import { COMMANDS, type TabOption } from "../lib/config"

export function useCodeBlock() {
  const [activeTab, setActiveTab] = useState<TabOption>("npm")
  const [copied, setCopied] = useState(false)

  const handleCopy = async () => {
    await navigator.clipboard.writeText(COMMANDS[activeTab])
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return { activeTab, setActiveTab, copied, handleCopy }
}

// Example: Fumadocs installation commands
export const TAB_OPTIONS = ["npm", "pnpm", "yarn", "bun"] as const
export type TabOption = (typeof TAB_OPTIONS)[number]

export const COMMANDS: Record<TabOption, string> = {
  npm: "npm i fumadocs-mdx fumadocs-core @types/mdx",
  pnpm: "pnpm add fumadocs-mdx fumadocs-core @types/mdx",
  yarn: "yarn add fumadocs-mdx fumadocs-core @types/mdx",
  bun: "bun add fumadocs-mdx fumadocs-core @types/mdx",
}

/* code-block — tabbed package-manager block, all classes scoped with cb- prefix */

/* ── Tokens ───────────────────────────────────────────────────────────────── */

.cb-root {
  --cb-bg:             #0a0a0a;
  --cb-border:         rgba(255, 255, 255, 0.10);
  --cb-tab-border:     rgba(255, 255, 255, 0.05);
  --cb-accent:         #facc15;
  --cb-tab-inactive:   rgba(255, 255, 255, 0.35);
  --cb-tab-hover:      rgba(255, 255, 255, 0.70);
  --cb-code-bg:        rgba(255, 255, 255, 0.03);
  --cb-copy:           rgba(255, 255, 255, 0.30);
  --cb-copy-hover:     rgba(255, 255, 255, 0.70);
  --cb-copy-hover-bg:  rgba(255, 255, 255, 0.05);
  --cb-syntax-cmd:     #4ade80;
  --cb-syntax-pkg:     #60a5fa;
}

/* ── Layout ───────────────────────────────────────────────────────────────── */

.cb-root {
  padding: 18px 14px;
  display: flex;
  justify-content: center;
  width: 100%;
}

.cb-inner {
  width: 100%;
  max-width: 680px;
}

.cb-card {
  overflow: hidden;
  border-radius: 0.5rem;
  border: 1px solid var(--cb-border);
  background: var(--cb-bg);
}

/* ── Tab row ──────────────────────────────────────────────────────────────── */

.cb-tabs {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding-inline: 1rem;
  border-bottom: 1px solid var(--cb-tab-border);
}

.cb-tab {
  padding-block: 0.5rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--cb-tab-inactive);
  background: none;
  border: none;
  cursor: pointer;
  transition: color 150ms ease;
}

.cb-tab:hover {
  color: var(--cb-tab-hover);
}

.cb-tab--active {
  color: var(--cb-accent);
}

/* Sliding underline */
.cb-indicator {
  position: absolute;
  bottom: 0;
  height: 1px;
  background: var(--cb-accent);
  transition: left 200ms ease-out, width 200ms ease-out;
  pointer-events: none;
}

/* Glow behind the indicator */
.cb-indicator-glow {
  position: absolute;
  bottom: 0;
  height: 0.5rem;
  background: color-mix(in srgb, var(--cb-accent) 25%, transparent);
  filter: blur(3px);
  transition: left 200ms ease-out, width 200ms ease-out;
  pointer-events: none;
}

/* ── Code row ─────────────────────────────────────────────────────────────── */

.cb-code {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.625rem 1rem;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 0.875rem;
  overflow-x: auto;
  background: var(--cb-code-bg);
}

.cb-cmd {
  display: inline-flex;
  text-align: left;
  white-space: nowrap;
  animation: cb-fade-in 0.15s ease-out forwards;
}

.cb-syntax-cmd  { color: var(--cb-syntax-cmd); }
.cb-syntax-pkg  { color: var(--cb-syntax-pkg); margin-left: 0.5rem; }
.cb-syntax-action { color: var(--cb-syntax-cmd); margin-left: 0.5rem; }

/* ── Copy button ──────────────────────────────────────────────────────────── */

.cb-copy-btn {
  flex-shrink: 0;
  padding: 0.25rem;
  border-radius: 0.25rem;
  border: none;
  background: none;
  color: var(--cb-copy);
  cursor: pointer;
  transition: color 150ms ease, background-color 150ms ease;
}

.cb-copy-btn:hover {
  color: var(--cb-copy-hover);
  background: var(--cb-copy-hover-bg);
}

.cb-copy-btn--copied {
  color: var(--cb-syntax-cmd);
}

/* ── Keyframes ────────────────────────────────────────────────────────────── */

@keyframes cb-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* ── Reduced motion ───────────────────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  .cb-indicator,
  .cb-indicator-glow {
    transition: none;
  }
  .cb-cmd {
    animation: none;
  }
}
